parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "answer": {
      "type": "string",
      "description": "The natural language answer to the customer"
    },
    "calculation_used": {
      "type": "boolean",
      "description": "Whether the calculator tool was used"
    },
    "result": {
      "type": "string",
      "description": "The numeric result if a calculation was performed, otherwise empty"
    }
  },
  "required": [
    "answer",
    "calculation_used"
  ]
}
